function icon(rec,big=false){if(!rec)return '';const manufacturer=rec.oem&&OEM_IMAGE_DATA[rec.oem]?`<img class="oem-icon" loading="lazy" alt="" src="${OEM_IMAGE_DATA[rec.oem]}">`:'<span class="no-oem-icon" aria-hidden="true">—</span>';return `<span class="icon-frame ${esc(rec.category)} ${rec.oem?'has-oem':'text-only'}" role="img" aria-label="${esc(rec.name)}${rec.oem?'':' · δεν διατίθεται ξεχωριστό εργοστασιακό εικονίδιο'}">${manufacturer}</span>`;}
function shuffleAssessmentOptions(){const shuffle=items=>{const copy=[...items];for(let i=copy.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]]}return copy};const questions=SCENARIOS.flatMap(scenario=>scenario.questions);const maxRun=slots=>slots.reduce((state,slot,index)=>{const run=index&&slot===slots[index-1]?state.run+1:1;return {run,max:Math.max(state.max,run)}},{run:0,max:0}).max;const base=questions.map((_,index)=>index%4);let slots=shuffle(base),attempts=0;while(maxRun(slots)>2&&attempts<40){slots=shuffle(base);attempts++}questions.forEach((question,index)=>{const correct=question.options[question.answer];const distractors=shuffle(question.options.filter((_,optionIndex)=>optionIndex!==question.answer));const target=slots[index]%question.options.length;question.options=distractors;question.options.splice(target,0,correct);question.answer=target})}
function renderCatalog(){const q=$('query').value.trim().toLocaleLowerCase('el');const found=RECORDS.filter(r=>(filter==='all'||r.category===filter)&&(power==='all'||r.variant==='all'||r.variant===power)&&(!q||[r.name,r.meaning,r.system,r.tech,r.ecu,r.variant].join(' ').toLocaleLowerCase('el').includes(q)));$('count').textContent=`${found.length} από ${RECORDS.length} ενδείξεις · έκδοση κινητήρα: ${power==='all'?'όλες':power}`;if(found.length&&!found.some(r=>r.id===chosen)){chosen=found[0].id;renderDetail()};$('lamp-grid').innerHTML=found.map(r=>`<button class="lamp ${r.id===chosen?'selected':''}" type="button" data-id="${esc(r.id)}" aria-pressed="${r.id===chosen}" aria-label="${esc(r.name)}">${icon(r)}<span class="name">${esc(r.name)}</span></button>`).join('')||'<div class="empty">Δεν βρέθηκαν ενδείξεις. Άλλαξε την αναζήτηση ή τα φίλτρα.</div>';$('lamp-grid').querySelectorAll('button[data-id]').forEach(b=>b.addEventListener('click',()=>{chosen=b.dataset.id;renderCatalog();renderDetail()}));}
function renderDetail(){const r=lampMap[chosen];if(!r)return;$('detail').innerHTML=`<div class="detail-top">${icon(r,true)}<div><h2>${esc(r.name)}</h2><div class="severity ${esc(r.category)}">${categoryLabels[r.category]}</div></div></div><h3>ΤΙ ΔΗΛΩΝΕΙ Η ΕΝΔΕΙΞΗ</h3><p>${esc(r.meaning)}</p><h3>ΕΝΕΡΓΕΙΑ ΟΔΗΓΟΥ / ΠΡΩΤΟΣ ΕΛΕΓΧΟΣ</h3><p>${esc(r.tech)}</p><h3>ΣΥΝΔΕΣΗ ΜΕ ECU, ΑΙΣΘΗΤΗΡΕΣ ΚΑΙ ΔΙΚΤΥΟ</h3><p>${esc(r.ecu)}</p><p class="manual-label"><b>Ενότητα:</b> ${esc(r.system)} · ${r.variant==='all'?'Όπου υπάρχει ο αντίστοιχος εξοπλισμός':esc(r.variant)}<br>Πηγή αναφοράς: εγχειρίδιο Clio 2024, σελ. 1.78–1.83, και επίσημος διαδικτυακός οδηγός Renault Clio 5. Η ακριβής ένδειξη και λειτουργία εξαρτάται από κινητήρα, έκδοση, εξοπλισμό και αγορά. Οι τεχνικές εξηγήσεις αποτελούν εκπαιδευτικές συσχετίσεις.</p>`;}
function activateTab(which){const exp=which==='explore';$('explore').classList.toggle('hidden',!exp);$('exam').classList.toggle('hidden',exp);$('tabExplore').classList.toggle('active',exp);$('tabExam').classList.toggle('active',!exp);$('tabExplore').setAttribute('aria-selected',String(exp));$('tabExam').setAttribute('aria-selected',String(!exp));if(!exp)renderCase();}
function key(c,q){return `${c}-${q}`;}function answered(){return Object.keys(answers).length;}
function renderCase(){if(finished){renderResult();return;}const c=SCENARIOS[caseIndex];$('exam-stats').innerHTML=`<div class="stat"><b>${caseIndex+1}/${SCENARIOS.length}</b><span>Περιστατικά</span></div><div class="stat"><b>${answered()}/${TOTAL_Q}</b><span>Απαντήσεις</span></div><div class="stat"><b>${TOTAL_Q}</b><span>Τεχνικές αποφάσεις</span></div>`;$('exam-content').innerHTML=`<article class="case-card"><div class="case-head"><div><div class="eyebrow">ΕΚΠΑΙΔΕΥΤΙΚΟ ΠΕΡΙΣΤΑΤΙΚΟ ${caseIndex+1}</div><h2>${esc(c.title)}</h2></div><div class="case-icons">${c.lamps.map(id=>icon(lampMap[id])).join('')}</div></div><p class="story">${esc(c.story)}</p>${c.questions.map((q,qi)=>`<div class="question"><h3>${qi+1}. ${esc(q.question)}</h3>${q.options.map((opt,oi)=>`<label class="option"><input name="q${qi}" type="radio" value="${oi}" ${answers[key(caseIndex,qi)]===oi?'checked':''}><span>${esc(opt)}</span></label>`).join('')}</div>`).join('')}<p class="pending">Κατά την αξιολόγηση οι σωστές απαντήσεις δεν εμφανίζονται.</p><div class="actions"><button id="prev" class="action" type="button" ${caseIndex===0?'disabled':''}>← Προηγούμενο</button><button id="next" class="action primary" type="button">${caseIndex===SCENARIOS.length-1?'Ολοκλήρωση αξιολόγησης':'Επόμενο περιστατικό →'}</button></div></article>`;$('exam-content').querySelectorAll('input[type=radio]').forEach(inp=>inp.addEventListener('change',()=>{answers[key(caseIndex,Number(inp.name.slice(1)))]=Number(inp.value);$('exam-stats').children[1].querySelector('b').textContent=`${answered()}/${TOTAL_Q}`;}));$('prev').onclick=()=>{if(caseIndex>0){caseIndex--;renderCase();scrollExam()}};$('next').onclick=()=>{if(caseIndex<SCENARIOS.length-1){caseIndex++;renderCase();scrollExam()}else{openSubmit()}};}
function scrollExam(){document.querySelector('.tabs').scrollIntoView({block:'start',behavior:'smooth'})}
function openSubmit(){const miss=TOTAL_Q-answered();$('submit-text').textContent=miss?`Έχεις αφήσει ${miss} από ${TOTAL_Q} απαντήσεις κενές. Θέλεις να επιστρέψεις ή να υποβάλεις όπως είναι;`:'Έχεις απαντήσει σε όλες τις ερωτήσεις. Θέλεις να δεις αποτέλεσμα και αιτιολογήσεις;';$('submit').classList.remove('hidden');$('confirm').focus();}
function renderResult(){let score=0,empty=0;let reviews='';SCENARIOS.forEach((c,ci)=>{c.questions.forEach((q,qi)=>{const a=answers[key(ci,qi)],ok=a===q.answer;if(ok)score++;if(a===undefined)empty++;reviews+=`<section class="review"><strong class="${ok?'correct':''}">${ok?'✓ Σωστό':'✕ '+(a===undefined?'Κενή απάντηση':'Χρειάζεται επανεξέταση')} · ${esc(c.title)} · ${qi+1}</strong><p>${esc(q.question)}</p><p><b>Σωστή απάντηση:</b> ${esc(q.options[q.answer])}</p><p><b>Αιτιολόγηση:</b> ${esc(q.explanation)}</p></section>`})});$('exam-stats').innerHTML='';$('exam-content').innerHTML=`<article class="case-card"><div class="eyebrow">ΤΕΛΙΚΟ ΑΠΟΤΕΛΕΣΜΑ</div><h2>Η αξιολόγηση ολοκληρώθηκε</h2><div class="resultscore">${score} / ${TOTAL_Q}</div><p>${Math.round(score*100/TOTAL_Q)}% σωστές τεχνικές αποφάσεις${empty?' · '+empty+' κενές':''}.</p><p class="pending">Εκπαιδευτικά, υποθετικά σενάρια: δεν υποκαθιστούν διαδικασίες επισκευής και ασφαλείας.</p><button type="button" class="action primary" id="repeat">Νέα προσπάθεια</button><h2>Αναλυτική ανασκόπηση</h2>${reviews}</article>`;$('repeat').onclick=()=>{answers={};caseIndex=0;finished=false;shuffleAssessmentOptions();renderCase();scrollExam()}}
shuffleAssessmentOptions();$('tabExplore').onclick=()=>activateTab('explore');$('tabExam').onclick=()=>activateTab('exam');$('query').addEventListener('input',renderCatalog);$('power').addEventListener('change',e=>{power=e.target.value;renderCatalog()});document.querySelectorAll('button[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('button[data-filter]').forEach(el=>{const yes=el===b;el.classList.toggle('active',yes);el.setAttribute('aria-pressed',String(yes))});renderCatalog()});$('cancel').onclick=()=>{$('submit').classList.add('hidden')};$('confirm').onclick=()=>{$('submit').classList.add('hidden');finished=true;renderResult();scrollExam()};document.addEventListener('keydown',e=>{if(e.key==='Escape')$('submit').classList.add('hidden')});renderCatalog();renderDetail();
